SELECT md5('facodi:ualg:1449:course-uc-link:'||u.code)::uuid,md5('facodi:ualg:1449:course')::uuid,md5('facodi:ualg:1449:uc:'||u.code)::uuid,
 'contains',u.position,'structured_catalog_import',
 jsonb_build_object('relation_origin','ualg_1449_official_2026_27_plan','official_code',u.code,'official_ects',u.ects,'curation_batch','facodi_ualg_1449_engenharia_civil_20261118')
